#include <iostream>
#include <string>

int main() {
    std::string line;
    if (std::getline(std::cin, line)) {
        int total = 0;
        size_t index = 0;
        while (index < line.length()) {
            size_t nextIndex = index + 1;
            while (nextIndex < line.length() && line[index] == line[nextIndex]) {
                nextIndex++;
            }
            total += ((nextIndex - index + 1) % 2);
            index = nextIndex;
        }
        std::cout << total << std::endl;
    }
    return 0;
}
